const GENERATED_OUTPUTS = new Set([
  "apps/pfotentechnik/src/domain/content/anchor-governance.generated.json",
  "apps/pfotentechnik/src/generated/content-quality-advisor.json",
]);
const RUNTIME_GENERATED_OUTPUTS = [
  "apps/pfotentechnik/src/generated/content-graph.json",
  "apps/pfotentechnik/reports/content-quality/content-inventory.json",
  "apps/pfotentechnik/reports/content-quality/content-inventory.csv",
  "apps/pfotentechnik/reports/content-quality/content-inventory.md",
  "apps/pfotentechnik/reports/content-quality/cannibalization-report.json",
  "apps/pfotentechnik/reports/content-quality/cannibalization-report.md",
  "apps/pfotentechnik/reports/content-quality/indexation-decisions.csv",
];
const args = new Set(process.argv.slice(2));
const checkOnly = args.has("--check");
const verify = !args.has("--no-verify");
const repoRoot = path.dirname(fileURLToPath(import.meta.url));
const hash = (buffer) => createHash("sha256").update(buffer).digest("hex");
const normalizeText = (buffer) => buffer.includes(0)
  ? buffer
  : Buffer.from(buffer.toString("utf8").replace(/\r\n/g, "\n"));
const normalizedHash = (buffer) => hash(normalizeText(buffer));
const packagePath = path.join(repoRoot, "package.json");

if (!fs.existsSync(path.join(repoRoot, ".git")) || !fs.existsSync(packagePath)) {
  throw new Error("Bitte den Installer im Root von Yushamon/affiliate-template ausführen.");
}
const rootPackage = JSON.parse(fs.readFileSync(packagePath, "utf8"));
if (rootPackage.name !== "affiliate-sites-monorepo") {
  throw new Error("Unerwartetes Repository: package.json passt nicht zu affiliate-template.");
}

const mergeRoot = fs.mkdtempSync(path.join(os.tmpdir(), LABEL + "-merge-"));
const mergeThreeWay = (entry, current) => {
  const safeName = createHash("sha1").update(entry.file).digest("hex");
  const currentPath = path.join(mergeRoot, safeName + "-current");
  const basePath = path.join(mergeRoot, safeName + "-base");
  const targetPath = path.join(mergeRoot, safeName + "-target");
  fs.writeFileSync(currentPath, normalizeText(current));
  fs.writeFileSync(basePath, normalizeText(Buffer.from(entry.beforeBase64, "base64")));
  fs.writeFileSync(targetPath, normalizeText(Buffer.from(entry.afterBase64, "base64")));
  const result = spawnSync("git", ["merge-file", "-p", currentPath, basePath, targetPath], {
    cwd: repoRoot,
    encoding: "buffer",
    maxBuffer: 32 * 1024 * 1024,
  });
  return {
    ok: result.status === 0,
    output: result.stdout,
    error: result.stderr?.toString("utf8").trim() || "git merge-file meldete einen Konflikt.",
  };
};

const states = ENTRIES.map((entry) => {
  const absolute = path.join(repoRoot, entry.file);
  const exists = fs.existsSync(absolute);
  const current = exists ? fs.readFileSync(absolute) : null;
  const currentHash = current ? normalizedHash(current) : null;
  const beforeHash = entry.beforeBase64
    ? normalizedHash(Buffer.from(entry.beforeBase64, "base64"))
    : null;
  const afterHash = entry.afterBase64
    ? normalizedHash(Buffer.from(entry.afterBase64, "base64"))
    : null;

  if (entry.action === "delete") {
    if (!exists) return { entry, state: "current" };
    if (currentHash === beforeHash) return { entry, state: "change", method: "delete" };
    return { entry, state: "conflict", reason: "Die zu konsolidierende Quelldatei enthält lokale Änderungen." };
  }

  if (currentHash === afterHash) return { entry, state: "current" };
  if (GENERATED_OUTPUTS.has(entry.file)) {
    return {
      entry,
      state: "change",
      method: exists ? "replace-generated" : "create-generated",
      outputBase64: entry.afterBase64,
    };
  }
  if (entry.action === "create") {
    if (!exists) return { entry, state: "change", method: "create", outputBase64: entry.afterBase64 };
    return { entry, state: "conflict", reason: "Eine andere Datei mit diesem neuen Namen existiert bereits." };
  }
  if (!exists) {
    return { entry, state: "conflict", reason: "Die erwartete Ausgangsdatei fehlt." };
  }
  if (currentHash === beforeHash) {
    return { entry, state: "change", method: "replace", outputBase64: entry.afterBase64 };
  }
  const merged = mergeThreeWay(entry, current);
  if (!merged.ok) {
    return { entry, state: "conflict", reason: merged.error };
  }
  if (normalizedHash(merged.output) === currentHash) {
    return { entry, state: "current", method: "already-merged" };
  }
  return {
    entry,
    state: "change",
    method: "three-way-merge",
    outputBase64: merged.output.toString("base64"),
  };
});
fs.rmSync(mergeRoot, { recursive: true, force: true });

const conflicts = states.filter((item) => item.state === "conflict");
if (conflicts.length > 0) {
  console.error("Abbruch: Für diese Dateien war keine sichere, konfliktfreie Installation möglich:");
  for (const item of conflicts) {
    console.error(" - " + item.entry.file);
    if (item.reason) console.error("   " + item.reason);
  }
  console.error("Es wurde nichts verändert. Bestehende Änderungen bleiben erhalten.");
  process.exit(2);
}

const pending = states.filter((item) => item.state === "change");
const skipped = states.filter((item) => item.state === "current");
if (checkOnly) {
  console.log(pending.length === 0
    ? "OK: Content-Inventory-Patch ist bereits vollständig installiert."
    : "OK: Content-Inventory-Patch ist konfliktfrei anwendbar (" + pending.length + " Dateien).");
  process.exit(0);
}

let backupRoot = null;
const backupIfPresent = (relative) => {
  const absolute = path.join(repoRoot, relative);
  if (!fs.existsSync(absolute)) return;
  const backup = path.join(backupRoot, relative);
  fs.mkdirSync(path.dirname(backup), { recursive: true });
  fs.copyFileSync(absolute, backup);
};

if (pending.length > 0) {
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  backupRoot = path.join(repoRoot, ".patch-backups", LABEL + "-" + stamp);
  fs.mkdirSync(backupRoot, { recursive: true });
  const manifest = {
    label: LABEL,
    createdAt: new Date().toISOString(),
    base: "pfotentechnik-performance-hardening-18.2.0",
    files: pending.map(({ entry, method }) => ({
      file: entry.file,
      action: entry.action,
      method,
      beforeHash: entry.beforeHash,
      afterHash: entry.afterHash,
    })),
    regeneratedOutputs: RUNTIME_GENERATED_OUTPUTS,
  };
  fs.writeFileSync(path.join(backupRoot, "manifest.json"), JSON.stringify(manifest, null, 2) + "\n");

  for (const { entry } of pending) backupIfPresent(entry.file);
  for (const output of RUNTIME_GENERATED_OUTPUTS) backupIfPresent(output);

  try {
    for (const item of pending) {
      const { entry } = item;
      const absolute = path.join(repoRoot, entry.file);
      if (entry.action === "delete") {
        fs.unlinkSync(absolute);
        continue;
      }
      fs.mkdirSync(path.dirname(absolute), { recursive: true });
      const temporary = absolute + ".tmp-" + process.pid;
      fs.writeFileSync(temporary, Buffer.from(item.outputBase64 ?? entry.afterBase64, "base64"));
      fs.chmodSync(temporary, entry.mode ?? 0o644);
      fs.renameSync(temporary, absolute);
    }
  } catch (error) {
    for (const { entry } of [...pending].reverse()) {
      const absolute = path.join(repoRoot, entry.file);
      const backup = path.join(backupRoot, entry.file);
      if (fs.existsSync(backup)) {
        fs.mkdirSync(path.dirname(absolute), { recursive: true });
        fs.copyFileSync(backup, absolute);
      } else if (fs.existsSync(absolute)) {
        fs.unlinkSync(absolute);
      }
    }
    console.error("Schreibfehler: Die bereits begonnenen Änderungen wurden zurückgerollt.");
    console.error(error.message);
    console.error("Backup: " + backupRoot);
    process.exit(3);
  }

  console.log("Installiert: " + pending.length + " Dateien geändert.");
  console.log("Geänderte Dateien:");
  for (const { entry, method } of pending) {
    console.log(" - " + entry.file + " (" + method + ")");
  }
  const mergedCount = pending.filter((item) => item.method === "three-way-merge").length;
  if (mergedCount) console.log("Bestehende Änderungen zusammengeführt: " + mergedCount + " Dateien.");
  console.log("Backup: " + backupRoot);
} else {
  console.log("Bereits installiert; keine Quelldateien verändert.");
}
if (skipped.length > 0) {
  console.log("Übersprungen, da bereits aktuell: " + skipped.length + " Dateien.");
  for (const { entry } of skipped) console.log(" - " + entry.file);
}

const run = (command, commandArgs) => {
  console.log("> " + command + " " + commandArgs.join(" "));
  const result = spawnSync(command, commandArgs, {
    cwd: repoRoot,
    stdio: "inherit",
    shell: process.platform === "win32",
    env: {
      ...process.env,
      ASTRO_TELEMETRY_DISABLED: "1",
      XDG_CONFIG_HOME: path.join(os.tmpdir(), "pfotentechnik-content-quality-xdg"),
    },
  });
  if (result.status !== 0) {
    console.error("Validierung fehlgeschlagen.");
    if (result.error) console.error("Prozessfehler: " + result.error.message);
    if (result.signal) console.error("Signal: " + result.signal);
    if (result.status !== null) console.error("Exit-Code: " + result.status);
    if (backupRoot) console.error("Originale liegen unter: " + backupRoot);
    process.exit(result.status ?? 1);
  }
};

if (pending.length > 0) {
  run(process.execPath, ["apps/pfotentechnik/scripts/build-content-graph.mjs"]);
}

if (verify) {
  const npm = process.platform === "win32" ? "npm.cmd" : "npm";
  const commands = [
    [npm, ["--workspace", "apps/pfotentechnik", "run", "test:content-quality"]],
    [npm, ["--workspace", "apps/pfotentechnik", "run", "test:seo-copilot"]],
    [npm, ["run", "build:pfotentechnik"]],
    [npm, ["--workspace", "apps/pfotentechnik", "run", "audit:content-quality:strict"]],
    [process.execPath, ["apps/pfotentechnik/scripts/seo/release-preflight.mjs", "--diagnostic", "--skip-build"]],
  ];
  for (const [command, commandArgs] of commands) run(command, commandArgs);
  console.log("Neu erzeugte oder aktualisierte Content-Quality-Reports:");
  for (const output of RUNTIME_GENERATED_OUTPUTS.filter((file) => file.includes("/reports/"))) {
    console.log(" - " + output);
  }
}

console.log("PfotenTechnik Content Inventory & Cannibalization 1.0.0 ist vollständig installiert.");
console.log("Es wurden keine Git-Commits, Pushes oder Pull Requests erzeugt.");
